  async loadSalesContribution(silent=false){if(!this.contributionFrom||!this.contributionTo)return;if(this.contributionFrom>this.contributionTo){if(!silent)this.notify('Tanggal kontribusi tidak valid.','error');return}this.contributionLoading=true;try{this.salesContribution=await this.api('sales_contribution',{query:{from:this.contributionFrom,to:this.contributionTo}});this.contributionSelected=null;const span=Math.round((new Date(this.contributionTo+'T12:00:00')-new Date(this.contributionFrom+'T12:00:00'))/86400000)+1;this.contributionRangeDays=[7,14,30,90].includes(span)?span:0}catch(e){if(!silent)this.notify(e.message,'error');else throw e}finally{this.contributionLoading=false}},
  contributionWindow(){const length=this.salesContribution?.series?.length||0;return length>180?30:length>60?14:length>14?7:length>7?3:1},
  contributionSeries(){const source=this.salesContribution?.series||[],windowSize=this.contributionWindow(),keys=['a5_20','a5_6','b5'];return source.map((day,index)=>{const from=Math.max(0,index-windowSize+1),qty={a5_20:0,a5_6:0,b5:0};for(let i=from;i<=index;i++)for(const key of keys)qty[key]+=Number(source[i].qty?.[key])||0;const total=keys.reduce((sum,key)=>sum+qty[key],0),share={};for(const key of keys)share[key]=total?qty[key]/total*100:0;return{...day,index,rollingQty:qty,rollingTotal:total,share}})},
  contributionChartX(index){const count=this.salesContribution?.series?.length||1;return count===1?418:58+(index/(count-1))*720},
