  contributionChartDateTicks(){const items=this.contributionSeries(),count=items.length;if(!count)return[];const wanted=Math.min(6,count),indexes=[];for(let i=0;i<wanted;i++)indexes.push(Math.round(i*(count-1)/Math.max(1,wanted-1)));return[...new Set(indexes)].map(index=>({index,label:items[index].label}))},
