  contributionShift(){const source=this.salesContribution?.series||[],keys=['a5_20','a5_6','b5'];if(source.length<2)return null;const size=Math.min(7,Math.max(1,Math.floor(source.length/2))),periodShare=rows=>{const qty={a5_20:0,a5_6:0,b5:0};for(const row of rows)for(const key of keys)qty[key]+=Number(row.qty?.[key])||0;const total=keys.reduce((sum,key)=>sum+qty[key],0);return Object.fromEntries(keys.map(key=>[key,total?qty[key]/total*100:0]))},start=periodShare(source.slice(0,size)),end=periodShare(source.slice(-size));let result=null;for(const key of keys){const delta=end[key]-start[key];if(!result||Math.abs(delta)>Math.abs(result.delta))result={key,delta,label:(this.salesContribution?.items||[]).find(item=>item.key===key)?.label||key}}return result},
