  async loadAnalytics(silent=false){if(!this.analyticsFrom||!this.analyticsTo)return;if(this.analyticsFrom>this.analyticsTo){if(!silent)this.notify('Tanggal mulai tidak boleh melewati tanggal akhir.','error');return}this.analyticsLoading=true;try{this.analytics=await this.api('dashboard_analytics',{query:{from:this.analyticsFrom,to:this.analyticsTo}});const span=Math.round((new Date(this.analyticsTo+'T12:00:00')-new Date(this.analyticsFrom+'T12:00:00'))/86400000)+1;this.analyticsRangeDays=[7,14,30,90].includes(span)?span:0}catch(e){if(!silent)this.notify(e.message,'error');else throw e}finally{this.analyticsLoading=false}},
