  addManualOrderItem(mapping){const existing=this.manualOrder.items.find(item=>item.mapping_id===mapping.id);if(existing)existing.qty++;else this.manualOrder.items.push({mapping_id:mapping.id,sku_id:mapping.sku_id,product_name:mapping.product_name,variation_name:mapping.variation_name,file_name:mapping.file_name,qty:1});this.manualOrder.query='';this.manualOrder.suggestions=[];this.loadManualOrderMappings()},
